import { escapeHtml as e } from './store.js';
import { selectedProfile, profileContext } from './profile-store.js';
import { PROFILE_MODEL_OPTIONS } from '../fixtures/profile-data.js';
const code = x => `<pre class="code-block">${e(JSON.stringify(x, null, 2))}</pre>`;
export function profileSelector(s, kind, id = s.dictationId, prefix = '') {
  const selected = selectedProfile(s, kind, id);
  return `<select ${prefix ? `id="${prefix}"` : `data-dictation-profile="${kind}"`} aria-label="${kind === 'recognizer' ? 'Recognizer' : 'Corrector'} profile">${s.profiles.filter(p => p.kind === kind).map(p => `<option value="${e(p.id)}" ${p.id === selected.id ? 'selected' : ''}>${e(p.name)} · ${e(p.model)} · v${p.version}</option>`).join('')}</select>`;
}
export function profileCard(s, kind) {
  const p = selectedProfile(s, kind);
  return `<section class="hub-card profile-summary"><div class="section-heading"><h3>${kind === 'recognizer' ? 'Recognizer' : 'Corrector'}</h3><span class="badge ${kind === 'recognizer' ? 'blue' : 'amber'}">${kind === 'recognizer' ? 'Audio → recognition evidence' : 'Text → suggestions only'}</span></div><p class="technical-note">${kind === 'recognizer' ? 'A reusable model and editable context prompt. Audio planning belongs to the run.' : 'A reusable model and editable instruction prompt. Each result requires human acceptance.'}</p>${profileSelector(s, kind)}<div class="profile-model-line"><span>Model ${e(p.model)}</span><span>Profile v${p.version}</span><span>${p.includePrimer ? 'Includes dictation primer' : 'Profile prompt only'}</span></div><details class="profile-prompt-preview"><summary>Profile prompt</summary><p>${e(p.prompt)}</p></details><button class="button small-button" data-action="edit-profile" data-id="${e(p.id)}">Edit profile</button></section>`;
}
export function profilesSettings(s) {
  const p = s.profileDraft || s.profiles.find(p => p.id === s.profileEditorId) || s.profiles[0], used = Object.values(s.dictationProfiles).filter(v => v[p.kind + 'Id'] === p.id).length;
  return `<h3>Recognizer & corrector profiles</h3><p class="modal-description">Each profile contains a model and editable prompt. Runs freeze a profile version. Saving affects future runs that select this profile.</p><div class="profile-settings-picker"><label class="setting-field"><span>Profile</span><select id="profile-picker">${s.profiles.map(p0 => `<option value="${e(p0.id)}" ${p0.id === p.id ? 'selected' : ''}>${p0.kind === 'recognizer' ? 'Recognizer' : 'Corrector'} · ${e(p0.name)}</option>`).join('')}</select></label><button class="button small-button" data-action="clone-profile" data-id="${e(p.id)}">Duplicate profile</button></div><div class="profile-type-banner"><strong>${p.kind === 'recognizer' ? 'Recognizer · audio → evidence' : 'Corrector · text → proposals'}</strong><span>v${p.version} · selected by ${used} dictations</span></div><label class="setting-field"><span>Profile name</span><input id="profile-name" value="${e(p.name)}" maxlength="100"/></label><label class="setting-field"><span>Model</span><select id="profile-model">${PROFILE_MODEL_OPTIONS[p.kind].map(m => `<option ${p.model === m ? 'selected' : ''}>${e(m)}</option>`).join('')}</select></label>${p.kind === 'corrector' ? `<label class="setting-field"><span>Suggestion policy</span><select id="profile-mode">${[['repair', 'Recognition repair'], ['cleanup', 'Cleanup'], ['editorial', 'Editorial rewrite suggestions']].map(([m, name]) => `<option value="${m}" ${p.mode === m ? 'selected' : ''}>${name}</option>`).join('')}</select></label>` : ''}<label class="setting-field"><span>${p.kind === 'recognizer' ? 'Recognition context prompt' : 'Correction instruction prompt'}</span><textarea id="profile-prompt" rows="7">${e(p.prompt)}</textarea></label><label class="profile-primer-toggle"><input id="profile-primer" type="checkbox" ${p.includePrimer ? 'checked' : ''}/>Include the dictation topic and confirmed terminology</label><div class="profile-save-row"><span>Changes are staged until saved.</span><button class="button primary small-button" data-action="save-profile">Save profile version</button></div><div class="quiet-note">${p.kind === 'corrector' ? 'Output contract: review proposals. This profile cannot enable direct document writes.' : p.model === 'gpt-live-transcribe' ? 'Native live input. Recorded-audio recognition uses a bounded model profile.' : 'Bounded audio input. Whole, partitioned, and growing-window plans share the same request executor.'}</div><details class="profile-prompt-preview"><summary>Compiled input for the open dictation</summary>${code(profileContext(s, p))}</details>`;
}
